/**
 * Differential tester: runs the reference executable and the Node port with
 * identical argv and compares stdout, stderr and exit status.
 *
 * The bootloader's `[PYI-<pid>:ERROR]` line embeds the live process id, so that
 * number is normalised before comparison. Nothing else is masked.
 *
 * Usage:
 *   node difftest.mjs            # run the built-in battery
 *   node difftest.mjs -- ARG...  # compare one explicit argv
 */

import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

function normalize(text) {
  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function runCase(argv, env) {
  const options = { encoding: 'utf8', env: { ...process.env, ...env } };
  const reference = spawnSync(REFERENCE, argv, options);
  const port = spawnSync('node', [PORT, ...argv], options);
  return {
    argv,
    env,
    ok:
      normalize(reference.stdout ?? '') === normalize(port.stdout ?? '')
      && normalize(reference.stderr ?? '') === normalize(port.stderr ?? '')
      && reference.status === port.status,
    reference: {
      stdout: reference.stdout, stderr: reference.stderr, status: reference.status,
    },
    port: { stdout: port.stdout, stderr: port.stderr, status: port.status },
  };
}

/** Argv vectors covering success, lookup failure and every argparse misuse. */
const CASES = [
  // documented samples
  ['--key', 'a', '--val', '83'],
  ['--key', 'a', '--val', '97'],
  ['--key', 'b', '--val', '21'],
  ['--key', 'b', '--val', '53'],
  // lookup failures
  ['--key', 'c', '--val', '1'],
  ['--key', 'A', '--val', '1'],
