/**
 * Node port of test2.py.
 *
 *   import argparse
 *   from bidict import bidict
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--key', type=str, required=True)
 *   parser.add_argument('--val', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   # 创建双向字典并访问值
 *   b = bidict({'a': 1, 'b': 2})
 *   result = b[args.key]
 *   print(result)
 *
 * Run as: node test2.mjs --key a --val 83
 */

import { ArgumentParser, str } from './lib/argparse/parser.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { print } from './lib/python/sys_io.mjs';
import { PyException, SystemExit } from './lib/python/exceptions.mjs';
import { reportUnhandled } from './lib/runtime/pyinstaller.mjs';

/**
 * The `<module>` frame of test2.py as a traceback sees it. Line 11 is
 * `result = b[args.key]`; columns 9..20 delimit the `b[args.key]` subscript that
 * raises, and are the offsets the code object would carry.
 */
const MODULE_FRAME = Object.freeze({
  file: 'test2.py',
  line: 11,
  name: '<module>',
  colno: 9,
  endColno: 20,
});

/** Name PyInstaller froze the entry script under. */
const SCRIPT_NAME = 'test2';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument(['--key'], { type: str, required: true });
  parser.addArgument(['--val'], { type: str, required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  // 创建双向字典并访问值
  // Passed as explicit pairs so key insertion order and value types (int, not
  // string) survive exactly as they do in the Python literal.
  const b = bidict([
    ['a', 1],
    ['b', 2],
  ]);
  const result = b.getItem(args.key);
  print(result);
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    process.exit(error.code);
  }
  if (error instanceof PyException) {
    // An uncaught Python exception: traceback, then exit status 1.
    reportUnhandled(error, [MODULE_FRAME], SCRIPT_NAME);
    process.exit(1);
  }
  throw error;
}

/**
 * CPython `repr()` / `str()` emulation, limited to the object kinds this
 * program can produce: str, int, float, bool and None.
 *
 * The string rules matter most here, because an unhandled KeyError prints
 * `repr()` of the missing key.
 */

import { codePoints, isPrintableCodePoint } from './unicode_props.mjs';

/** Marker object standing in for Python's `None`. */
export const NONE = Symbol('None');

function hexEscape(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * Mirrors CPython's `unicode_repr`.
 *
 * Quote selection: single quotes by default; double quotes when the string
 * contains a single quote but no double quote. Only then does `'` need
 * escaping.
 *
 * @param {string} value
 * @returns {string}
 */
export function reprStr(value) {
  const hasSingle = value.includes("'");
  const hasDouble = value.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const codePoint of codePoints(value)) {
    if (codePoint === 0x5c) {
      out += '\\\\';
    } else if (codePoint === quote.charCodeAt(0)) {
      out += `\\${quote}`;
    } else if (codePoint === 0x09) {
      out += '\\t';
    } else if (codePoint === 0x0a) {
      out += '\\n';
    } else if (codePoint === 0x0d) {
      out += '\\r';
    } else if (isPrintableCodePoint(codePoint)) {
      out += String.fromCodePoint(codePoint);
    } else {
      out += hexEscape(codePoint);
    }
  }
  return out + quote;
}

/**
 * Renders an integer the way Python does. Values are carried as JS numbers or
 * BigInt; both print without a fractional part or exponent.
 *
 * @param {number|bigint} value
 * @returns {string}
 */
export function reprInt(value) {
  return typeof value === 'bigint' ? value.toString() : String(value);
}

/**
 * Renders a Python float. Python uses `repr` shortest-roundtrip formatting and
 * always keeps a decimal point or exponent.
 *
 * @param {number} value
 * @returns {string}
 */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  let text = String(value);
  if (text.includes('e')) {
    // JS writes 1e+21, Python writes 1e+21 as well, but Python pads the
    // exponent to at least two digits.
    const [mantissa, exponent] = text.split('e');
    const sign = exponent.startsWith('-') ? '-' : '+';
    const digits = exponent.replace(/^[+-]/, '').padStart(2, '0');
    return `${mantissa}e${sign}${digits}`;
  }
  return text.includes('.') ? text : `${text}.0`;
}

/**
 * Dispatches to the right renderer. Booleans are checked before numbers
 * because Python's bool is a subclass of int but reprs as True/False.
 *
 * @param {*} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === NONE || value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'number') {
    return Number.isInteger(value) ? reprInt(value) : reprFloat(value);
  }
  if (value && typeof value.__repr__ === 'function') return value.__repr__();
  return String(value);
}

/**
 * Mirrors `str()`, which differs from `repr()` only in that strings are
 * returned unquoted.
 *
 * @param {*} value
 * @returns {string}
 */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  if (value && typeof value.__str__ === 'function') return value.__str__();
  return pyRepr(value);
}

