// Reusable differential harness with concurrency. Compares reference vs port.
import { spawn } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

export function normalize(text) {
  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function run(cmd, args, opts = {}) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, {
      env: { ...process.env, ...(opts.env || {}) },
      cwd: opts.cwd || process.cwd(),
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const out = [];
    const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', (e) => resolve({ stdout: '', stderr: `SPAWNERR ${e.message}`, status: null }));
    child.on('close', (code, signal) => resolve({
      stdout: Buffer.concat(out).toString('utf8'),
      stderr: Buffer.concat(err).toString('utf8'),
      stdoutRaw: Buffer.concat(out),
      stderrRaw: Buffer.concat(err),
      status: signal ? `signal:${signal}` : code,
    }));
  });
}

export async function runCase(argv, opts = {}) {
  const [reference, port] = await Promise.all([
    run(REFERENCE, argv, opts),
    run('node', [PORT, ...argv], opts),
  ]);
  const ok = normalize(reference.stdout) === normalize(port.stdout)
    && normalize(reference.stderr) === normalize(port.stderr)
    && reference.status === port.status;
  return { argv, opts, ok, reference, port };
}

export async function runAll(cases, { concurrency = 24, onResult } = {}) {
  const results = [];
  let index = 0;
  async function worker() {
    for (;;) {
      const i = index++;
      if (i >= cases.length) return;
      const c = cases[i];
      const r = await runCase(c.argv, c.opts || {});
      r.label = c.label;
      results[i] = r;
      if (onResult) onResult(r, i);
    }
  }
  await Promise.all(Array.from({ length: concurrency }, worker));
  return results;
}

// Exhaustive sweep: every code point 0x01..0x10FFFF (minus surrogates) batched
// into --key strings. One differing code point makes the batch's repr differ.
import { runAll } from './harness.mjs';

const BATCH = Number(process.argv[2] || 512);
const START = Number(process.argv[3] || 0x01);
const END = Number(process.argv[4] || 0x10ffff);

const points = [];
for (let cp = START; cp <= END; cp += 1) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue; // cannot survive Node argv
  points.push(cp);
}

const batches = [];
for (let i = 0; i < points.length; i += BATCH) batches.push(points.slice(i, i + BATCH));

const cases = batches.map((b) => ({
  argv: [`--key=${b.map((cp) => String.fromCodePoint(cp)).join('')}`, '--val=1'],
  label: b,
}));

let bad = 0;
const failing = [];
const results = await runAll(cases, {
  concurrency: 32,
  onResult(r) {
    if (!r.ok) { bad += 1; failing.push(r.label); }
  },
});

// Bisect each failing batch down to individual code points.
async function isolate(list) {
  if (list.length === 0) return [];
  const cs = list.map((cp) => ({
    argv: [`--key=${String.fromCodePoint(cp)}`, '--val=1'],
    label: cp,
  }));
  const rs = await runAll(cs, { concurrency: 32 });
  return rs.filter((r) => !r.ok).map((r) => r.label);
}

const suspects = failing.flat();
const single = await isolate(suspects);

console.log(`batches=${cases.length} failingBatches=${bad} codepointsInFailingBatches=${suspects.length}`);
console.log(`singleCharDivergences=${single.length}`);
if (single.length) {
  const grouped = [];
  for (const cp of single) {
    const last = grouped[grouped.length - 1];
    if (last && last[1] + 1 === cp) last[1] = cp;
    else grouped.push([cp, cp]);
  }
  console.log(grouped.map(([a, b]) => (a === b ? `U+${a.toString(16).toUpperCase()}` : `U+${a.toString(16).toUpperCase()}..U+${b.toString(16).toUpperCase()}`)).join(' '));
}
console.log(`totalCasesRun=${cases.length + suspects.length}`);

