function norm(t) { return t.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]'); }

function sh(cmd) {
  return new Promise((resolve) => {
    const c = spawn('/bin/bash', ['-c', cmd], { stdio: ['ignore', 'pipe', 'pipe'] });
    const o = []; const e = [];
    c.stdout.on('data', (d) => o.push(d));
    c.stderr.on('data', (d) => e.push(d));
    c.on('close', (code) => resolve({
      stdout: Buffer.concat(o), stderr: Buffer.concat(e), status: code,
    }));
  });
}

const octal = (bytes) => bytes.map((b) => `\\${b.toString(8).padStart(3, '0')}`).join('');
const cmdFor = (bin, bytes) => `${bin} "--key=$(printf '${octal(bytes)}')" --val=1`;

async function one(bytes) {
  const [r, p] = await Promise.all([sh(cmdFor(REF, bytes)), sh(cmdFor(PORT, bytes))]);
  const ok = norm(r.stdout.toString('binary')) === norm(p.stdout.toString('binary'))
    && norm(r.stderr.toString('binary')) === norm(p.stderr.toString('binary'))
    && r.status === p.status;
